#[derive(Debug, Clone)]
pub(crate) struct ManagedModelConfig {
    pub(crate) config: ManagedLocalModelConfig,
}

pub(crate) fn managed_model_capability_profile(model_id: &str) -> ModelCapabilityProfile {
    ModelCapabilityProfile {
        backend_id: MANAGED_BACKEND_ID,
        model_id: model_id.trim().to_owned(),
        structured_output: Some(false),
        tool_use: Some(false),
        image_input: Some(false),
        reasoning: None,
        context_limit: None,
        streaming: Some(false),
        usage: Some(true),
        resource_capabilities: ModelResourceCapabilities {
            representation_size: CapabilityAvailability::Available,
            gpu_residency: CapabilityAvailability::Unavailable,
            cpu_gpu_offload: CapabilityAvailability::Unavailable,
            selectable_device: CapabilityAvailability::Unavailable,
            kv_context_placement: CapabilityAvailability::Unavailable,
            inference_cache_release: CapabilityAvailability::Unavailable,
            unload_reload: CapabilityAvailability::Available,
            backend_memory_telemetry: CapabilityAvailability::Unavailable,
        },
        benchmark_verified: false,
    }
}

impl ManagedModelConfig {
    pub(crate) fn capability_profile(&self) -> ModelCapabilityProfile {
        managed_model_capability_profile(&self.config.model_id)
    }

    pub(crate) fn installed_inventory(&self) -> InstalledModelInventory {
        InstalledModelInventory {
            endpoint: format!(
                "managed://{}",
                self.config.environment.benchmark_id()
            ),
            backend_version: Some(self.config.benchmark_runtime_identity()),
            execution_environment: Some(
                self.config.environment.benchmark_id().to_owned(),
            ),
            launch_policy_version: Some(MANAGED_LAUNCH_POLICY_VERSION.to_owned()),
            models: vec![InstalledLocalModel {
                name: self.config.model_id.clone(),
                digest: Some(self.config.model_content_sha256.clone()),
                size_bytes: Some(self.config.model_size_bytes),
                parameter_size: None,
                quantization_level: self.config.quantization.clone(),
                family: Some("GGUF".to_owned()),
            }],
        }
    }
}

#[derive(Debug, Clone)]
pub(crate) enum NativeModelConfig {
    Local(LocalModelConfig),
    Managed(ManagedModelConfig),
    Hosted(HostedModelConfig),
}
